INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''tech pack'' (technical package) in apparel product development?', '["A comprehensive document containing all specifications (measurements, materials, construction details, trims) needed to manufacture a garment","The physical packaging box a finished garment ships in","A software program used only for pattern digitizing","A record of a factory''s compliance/audit certifications"]'::jsonb, 'A comprehensive document containing all specifications (measurements, materials, construction details, trims) needed to manufacture a garment', 'A tech pack consolidates all the technical information a factory needs — measurement specs, fabric/trim details, construction/stitch specs, color ways, labeling — into one reference document guiding accurate garment production.', 1, '{"tech-pack"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''point of measure'' (POM) in a garment spec sheet?', '["A specific location on a garment (e.g., chest width, sleeve length) where a measurement must be taken and verified against a tolerance","The retail point-of-sale location where a garment is sold","A quality control checkpoint on the sewing line","The exact price point of a finished garment"]'::jsonb, 'A specific location on a garment (e.g., chest width, sleeve length) where a measurement must be taken and verified against a tolerance', 'POMs define exact measurement locations (like chest width at a specific point below the armhole, or sleeve length) with target values and tolerances, used to check whether a produced garment matches its intended specification.', 1, '{"point-of-measure"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'Why do garment spec sheets include a measurement ''tolerance'' (e.g., ± 0.5 cm) rather than requiring an exact measurement?', '["Natural variation in fabric, cutting, and sewing makes hitting an exact measurement every single time impractical; a tolerance defines an acceptable range around the target","Tolerances exist purely as a formality with no practical manufacturing reason","Exact measurements are always easily achievable with zero variation in real production","Tolerance only applies to fabric color, never to physical dimensions"]'::jsonb, 'Natural variation in fabric, cutting, and sewing makes hitting an exact measurement every single time impractical; a tolerance defines an acceptable range around the target', 'Because fabric behavior, cutting precision, and sewing all have natural small variations, requiring a perfectly exact measurement on every single garment is unrealistic; tolerances define how much deviation from the target is still acceptable for the garment to pass quality inspection.', 2, '{"measurement-tolerance"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''seam allowance'' in garment construction?', '["The extra fabric width beyond the stitch line, needed to physically join two fabric pieces together","The total fabric consumption for an entire garment","The gap left between buttons on a shirt placket","The distance between the collar and the first button"]'::jsonb, 'The extra fabric width beyond the stitch line, needed to physically join two fabric pieces together', 'Seam allowance is the extra fabric between the cut edge and the stitching line — without it, there would be no fabric for the seam itself to grip, so pattern pieces are cut larger than the finished garment shape to include this allowance.', 1, '{"seam-allowance"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''ease'' in a garment pattern (e.g., ''wearing ease'')?', '["Extra room built into a garment''s measurements beyond the body''s exact dimensions, allowing comfortable movement and fit","The physical effort required to sew a particular garment style","A finishing technique that softens fabric hand-feel","The speed at which a garment can be produced on the line"]'::jsonb, 'Extra room built into a garment''s measurements beyond the body''s exact dimensions, allowing comfortable movement and fit', 'Ease is the deliberate extra room added to a pattern beyond exact body measurements, needed for comfortable movement (wearing ease) and/or for the garment''s intended silhouette (design ease) — different garment types and fits require different amounts.', 1, '{"garment-ease"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'Why might a fitted garment (e.g., a slim-fit shirt) and an oversized garment of the SAME body-size label have very different actual chest measurements?', '["They''re designed with different amounts of ease — the oversized style deliberately includes much more extra room beyond body measurements than the fitted style","Garments of the same size label must always have identical measurements regardless of intended fit","Ease only applies to sleeve length, never to chest width","Fit style has no relationship to ease allowance in pattern design"]'::jsonb, 'They''re designed with different amounts of ease — the oversized style deliberately includes much more extra room beyond body measurements than the fitted style', 'Since ease is a deliberate design choice, two garments sharing the same size label but different intended silhouettes (slim-fit vs. oversized) can have substantially different actual finished measurements — the label indicates target body size, not the garment''s exact finished dimensions.', 2, '{"ease-vs-size-label"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''grain line'' marked on a pattern piece, and why does it matter during cutting?', '["A line indicating the direction the pattern piece must align with the fabric''s warp (lengthwise) yarn direction, ensuring correct drape and stability","A decorative marking with no functional purpose during cutting","A line indicating where buttons should be sewn","A marking used only for fabric quality inspection, unrelated to pattern placement"]'::jsonb, 'A line indicating the direction the pattern piece must align with the fabric''s warp (lengthwise) yarn direction, ensuring correct drape and stability', 'Grain line marks on a pattern piece must align with the fabric''s lengthwise (warp) grain when cutting; cutting off-grain can cause the finished garment to hang/drape incorrectly, twist after washing, or stretch unpredictably.', 1, '{"grain-line"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What happens if a pattern piece is cut significantly OFF the correct fabric grain line?', '["The finished garment section may hang, drape, or twist incorrectly, and may distort more than intended during wear or washing","Cutting off-grain always improves the garment''s fit and drape","Grain direction has no effect on how a finished garment hangs or behaves","Off-grain cutting only affects fabric color consistency, not garment shape"]'::jsonb, 'The finished garment section may hang, drape, or twist incorrectly, and may distort more than intended during wear or washing', 'Fabric behaves differently along its warp, weft, and bias directions (stretch, drape, stability); cutting a pattern piece off the intended grain line means that piece won''t hang or behave as designed, often causing visible twisting, uneven hem, or excess distortion after wear/washing.', 2, '{"off-grain-cutting-defect"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''topstitching'' in garment construction?', '["Visible stitching sewn on the outside/right side of a garment, often for both decorative effect and added seam strength","Stitching that is always completely hidden inside the garment","The very first stitch line sewn when starting garment construction","A stitch used exclusively for attaching zippers"]'::jsonb, 'Visible stitching sewn on the outside/right side of a garment, often for both decorative effect and added seam strength', 'Topstitching is deliberately visible stitching on a garment''s outer surface (like on jeans pockets or shirt collars), serving both a decorative role and often reinforcing the seam or edge it''s applied to.', 1, '{"topstitching"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''placket'' on a garment (e.g., a shirt front placket)?', '["A reinforced fabric strip, often where buttons/buttonholes are located, providing structure to an opening","The collar of a shirt","The cuff at the end of a sleeve","A decorative pocket flap"]'::jsonb, 'A reinforced fabric strip, often where buttons/buttonholes are located, providing structure to an opening', 'A placket is a structured fabric strip (often interlined/fused) that reinforces a garment opening — like a shirt''s button front — giving it the stability needed to withstand repeated buttoning/unbuttoning without stretching or distorting.', 1, '{"placket"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'Why is a garment''s front button placket typically interlined/fused, while other areas of the same shirt may not be?', '["The placket experiences repeated stress from buttoning/unbuttoning and needs extra structure/stability that a single fabric layer alone wouldn''t provide","Interlining is applied uniformly to every part of a garment with zero exceptions","Interlining exists purely for decorative appearance, unrelated to any functional stress point","The placket is interlined only to change its color slightly"]'::jsonb, 'The placket experiences repeated stress from buttoning/unbuttoning and needs extra structure/stability that a single fabric layer alone wouldn''t provide', 'Areas subject to repeated mechanical stress (like a button placket being pulled/stressed with every buttoning) benefit from interlining''s added structure and stability, preventing the fabric from stretching, sagging, or losing shape over repeated use — while non-stressed areas don''t need this extra reinforcement.', 2, '{"interlining-application"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What is ''shade banding'' (or shading) as a garment quality defect?', '["Visible color/shade variation between different panels or components of the same garment, from fabric dyed in different lots","A deliberate decorative color-blocking design","A defect that only affects buttons, not fabric","A stitching irregularity unrelated to color"]'::jsonb, 'Visible color/shade variation between different panels or components of the same garment, from fabric dyed in different lots', 'Shade banding appears when different garment panels (front, back, sleeves) were cut from fabric of slightly different dye lots, creating a visible, unintended color mismatch across the same finished garment — a quality defect that proper fabric lot control during cutting helps prevent.', 2, '{"shade-banding"}'::text[]);
